  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "npm run build && node --test \"dist/test/**/*.test.js\"",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "arch": "depcruise src --config .dependency-cruiser.cjs --ignore-known"
  }
}

