} as const;

const SKU_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * Builds a placed order after checking every invariant:
 * at least one line, positive integer quantities, prices as integer minor units,
 * a supported currency and a bounded total. All problems are reported together.
 */
export function createOrder(input: NewOrder, meta: { id: string; placedAt: string }): Order {
  const issues = collectIssues(input);
  if (issues.length > 0) {
    throw new ValidationError(issues);
  }
  return {
    id: meta.id,
    customerId: input.customerId,
    customerEmail: input.customerEmail,
    lines: input.lines.map((line) => ({
      sku: line.sku,
      name: line.name,
      qty: line.qty,
      unitPriceCents: line.unitPriceCents,
    })),
    status: "placed",
    currency: input.currency,
    placedAt: meta.placedAt,
  };
}

/** Orders can be cancelled this long after they were placed. */
export const CANCELLATION_WINDOW_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

export function canCancel(order: Order, at: string): boolean {
  if (order.status !== "placed") {
    return false;
  }
  const elapsed = Date.parse(at) - Date.parse(order.placedAt);
  return elapsed <= CANCELLATION_WINDOW_DAYS * DAY_MS;
}

export function cancel(order: Order, cancelledAt: string): Order {
  if (!canCancel(order, cancelledAt)) {
    const reason = order.status === "placed" ? "cancelled after the cancellation window" : "cancelled";
    throw new InvalidStateError(order.id, order.status, reason);
  }
  return { ...order, status: "cancelled", cancelledAt };
}

/** Order total in minor units: the sum of qty x unit price over all lines. */
export function totalCents(order: Pick<Order, "lines" | "currency">): number {
  const lineTotals = order.lines.map((line) => multiply(money(line.unitPriceCents, order.currency), line.qty));
  return sum(lineTotals, order.currency).amountMinor;
}

function collectIssues(input: NewOrder): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const fail = (path: string, message: string): void => {
    issues.push({ path, message });
  };

  if (!isNonBlank(input.customerId) || input.customerId.length > LIMITS.maxIdLength) {
    fail("customerId", `must be 1-${LIMITS.maxIdLength} characters`);
  }
  if (
    typeof input.customerEmail !== "string" ||
    input.customerEmail.length > LIMITS.maxEmailLength ||
    !EMAIL_PATTERN.test(input.customerEmail)
  ) {
    fail("customerEmail", "must be a valid email address");
  }
  if (!isSupportedCurrency(input.currency)) {
    fail("currency", "must be a supported ISO-4217 currency code");
  }
  if (!Array.isArray(input.lines) || input.lines.length === 0) {
    fail("lines", "must contain at least one line");
    return issues;
  }
  if (input.lines.length > LIMITS.maxLines) {
    fail("lines", `must contain at most ${LIMITS.maxLines} lines`);
  }

  let runningTotal = 0;
  input.lines.forEach((line, index) => {
    const at = `lines[${index}]`;
    if (typeof line.sku !== "string" || line.sku.length > LIMITS.maxSkuLength || !SKU_PATTERN.test(line.sku)) {
      fail(`${at}.sku`, "must be an alphanumeric SKU of at most 64 characters");
    }
    if (!isNonBlank(line.name) || line.name.length > LIMITS.maxNameLength) {
      fail(`${at}.name`, `must be 1-${LIMITS.maxNameLength} characters`);
    }
    if (!Number.isInteger(line.qty) || line.qty < 1 || line.qty > LIMITS.maxQtyPerLine) {
      fail(`${at}.qty`, `must be an integer between 1 and ${LIMITS.maxQtyPerLine}`);
    }
    if (!isMinorUnits(line.unitPriceCents)) {
      fail(`${at}.unitPriceCents`, "must be a non-negative integer (minor units)");
      return;
    }
    if (Number.isInteger(line.qty) && line.qty > 0) {
      runningTotal += line.qty * line.unitPriceCents;
    }
  });
  if (runningTotal > LIMITS.maxTotalMinor) {
    fail("lines", `order total exceeds the maximum of ${LIMITS.maxTotalMinor} minor units`);
  }
  return issues;
}

function isNonBlank(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}
import { totalCents, type Order } from "./order.js";

export const ORDER_PLACED_TOPIC = "orders.placed";
export const ORDER_CANCELLED_TOPIC = "orders.cancelled";

/** Published when an order has been accepted and its payment authorized. */
export interface OrderPlaced {
  readonly type: "OrderPlaced";
  readonly schemaVersion: 3;
  readonly orderId: string;
  readonly customerId: string;
  /** Legacy field; a known ARCH-6 exception tracked in the PII baseline. */
  readonly customerEmail: string;
  /** ISO-8601 instant. */
  readonly placedAt: string;
  /** ISO-4217 code. */
  readonly currency: string;
  /** Integer, minor units. */
  readonly totalCents: number;
  readonly lines: ReadonlyArray<{
    readonly sku: string;
    readonly qty: number;
    readonly unitPriceCents: number;
  }>;
}

/** Published when a placed order is cancelled. */
export interface OrderCancelled {
  readonly type: "OrderCancelled";
  readonly schemaVersion: 1;
  readonly orderId: string;
  readonly customerId: string;
  /** ISO-8601 instant. */
  readonly cancelledAt: string;
  readonly reason?: string;
}

export type DomainEvent = OrderPlaced | OrderCancelled;

/** The single place where an `OrderPlaced` event is built. */
export function orderPlaced(order: Order): OrderPlaced {
  return {
    type: "OrderPlaced",
    schemaVersion: 3,
    orderId: order.id,
    customerId: order.customerId,
    customerEmail: order.customerEmail,
    placedAt: order.placedAt,
    currency: order.currency,
    totalCents: totalCents(order),
    lines: order.lines.map((line) => ({
      sku: line.sku,
      qty: line.qty,
      unitPriceCents: line.unitPriceCents,
    })),
  };
}

/** The single place where an `OrderCancelled` event is built. */
export function orderCancelled(order: Order, cancelledAt: string, reason?: string): OrderCancelled {
  return {
    type: "OrderCancelled",
    schemaVersion: 1,
    orderId: order.id,
    customerId: order.customerId,
    cancelledAt,
    ...(reason === undefined ? {} : { reason }),
  };
}

export function topicFor(event: DomainEvent): string {
  switch (event.type) {
    case "OrderPlaced":
      return ORDER_PLACED_TOPIC;
    case "OrderCancelled":
      return ORDER_CANCELLED_TOPIC;
  }
}

/** Partition key: all events of one order are ordered relative to each other. */
export function partitionKeyFor(event: DomainEvent): string {
  return event.orderId;
}
import { ValidationError, type ValidationIssue } from "../core/errors.js";
import type { NewOrder, OrderLine, OrderStatus } from "../core/order.js";
import type { CustomerOrdersQuery } from "../core/ports.js";
import { decodeCursor } from "./cursor.js";
import { InputReader, isJsonObject } from "./inputReader.js";

/**
 * Turns the untrusted body of `POST /orders` into a typed command.
 * Only the shape is checked here; the core enforces the business invariants.
 */
export function parsePlaceOrderRequest(body: unknown): NewOrder {
  if (!isJsonObject(body)) {
    throw new ValidationError([{ path: "body", message: "must be a JSON object" }]);
  }
  const reader = new InputReader(body);
  const customerId = reader.string("customerId");
  const customerEmail = reader.string("customerEmail");
  const currency = reader.string("currency");

  const lines: OrderLine[] = [];
  reader.array("lines").forEach((raw, index) => {
    const line = reader.object(`lines[${index}]`, raw);
    if (line === undefined) {
      return;
    }
    lines.push({
      sku: line.string("sku"),
      name: line.string("name"),
      qty: line.number("qty"),
      unitPriceCents: line.number("unitPriceCents"),
    });
    reader.issues.push(...line.issues);
  });

  if (reader.issues.length > 0) {
    throw new ValidationError(reader.issues);
  }
  return { customerId, customerEmail, currency, lines };
}

export interface CancelOrderRequest {
  readonly reason?: string;
}

/** The body of `POST /orders/{id}/cancel` is optional: `{ "reason"?: string }`. */
export function parseCancelRequest(body: unknown): CancelOrderRequest {
  if (body === undefined || body === null) {
    return {};
  }
  if (!isJsonObject(body)) {
    throw new ValidationError([{ path: "body", message: "must be a JSON object" }]);
  }
  const reader = new InputReader(body);
  const reason = reader.optionalString("reason");
  if (reason !== undefined && reason.length > 200) {
    reader.fail("reason", "must be at most 200 characters");
  }
  if (reader.issues.length > 0) {
    throw new ValidationError(reader.issues);
  }
  return reason === undefined ? {} : { reason };
}

const DEFAULT_LIST_LIMIT = 20;
const STATUSES: readonly string[] = ["placed", "cancelled"];

/** Query of `GET /orders?customerId=...[&status=placed|cancelled][&limit=1..100][&cursor=...]`. */
export function parseListOrdersQuery(params: URLSearchParams): CustomerOrdersQuery {
  const issues: ValidationIssue[] = [];
  const customerId = params.get("customerId") ?? "";
  if (customerId.trim() === "") {
    issues.push({ path: "customerId", message: "is required" });
  }
  const status = params.get("status");
  if (status !== null && !STATUSES.includes(status)) {
    issues.push({ path: "status", message: `must be one of ${STATUSES.join(", ")}` });
  }
  const rawLimit = params.get("limit");
  if (rawLimit !== null && !/^\d+$/.test(rawLimit)) {
    issues.push({ path: "limit", message: "must be a positive integer" });
  }
  if (issues.length > 0) {
    throw new ValidationError(issues);
  }
  const limit = rawLimit === null ? DEFAULT_LIST_LIMIT : Number(rawLimit);
  const cursor = params.get("cursor");
  return {
    customerId,
    limit,
    ...(status === null ? {} : { status: status as OrderStatus }),
    ...(cursor === null ? {} : { after: decodeCursor(cursor) }),
  };
}
